// Creating a simple Promise
const myPromise = new Promise((resolve, reject) => {
  setTimeout(() => {
    resolve('Success!');
  }, 1000);
});

// Handling the Promise result
myPromise.then((result) => {
  console.log(result); // Logs 'Success!' after 1 second
}).catch((error) => {
  console.log(error);
});
